-- Run in Supabase SQL Editor
create table if not exists public.players(id text primary key,name_en text not null,name_ar text not null,active boolean not null default true,created_at timestamptz not null default now());
insert into public.players(id,name_en,name_ar,active) values('cr7','Cristiano Ronaldo','كريستيانو رونالدو',true),('m10','Lionel Messi','ليونيل ميسي',true),('mb9','Kylian Mbappé','كيليان مبابي',true),('ha7','Erling Haaland','إيرلينغ هالاند',true) on conflict(id) do nothing;
create table if not exists public.verified_votes(id bigint generated always as identity primary key,player_id text not null references public.players(id),stripe_session_id text not null unique,payment_intent_id text unique,amount_cents integer not null check(amount_cents=100),currency text not null check(currency='usd'),created_at timestamptz not null default now());
alter table public.players enable row level security;alter table public.verified_votes enable row level security;
drop policy if exists "Public can read active players" on public.players;create policy "Public can read active players" on public.players for select using(active=true);
create or replace view public.public_vote_totals as select p.id as player_id,coalesce(v.vote_count,0)::bigint as vote_count from public.players p left join(select player_id,count(*) as vote_count from public.verified_votes group by player_id)v on v.player_id=p.id where p.active=true;
create or replace function public.record_verified_vote(p_player_id text,p_stripe_session_id text,p_payment_intent_id text,p_amount_cents integer,p_currency text) returns boolean language plpgsql security definer set search_path=public as $$ begin if p_amount_cents<>100 or lower(p_currency)<>'usd' then raise exception 'Invalid vote payment amount or currency';end if;if not exists(select 1 from public.players where id=p_player_id and active=true)then raise exception 'Unknown or inactive player';end if;insert into public.verified_votes(player_id,stripe_session_id,payment_intent_id,amount_cents,currency) values(p_player_id,p_stripe_session_id,p_payment_intent_id,p_amount_cents,lower(p_currency)) on conflict do nothing;return found;end;$$;
revoke all on function public.record_verified_vote(text,text,text,integer,text) from public,anon,authenticated;grant execute on function public.record_verified_vote(text,text,text,integer,text) to service_role;grant select on public.public_vote_totals to anon,authenticated;
